(async()=>{const out={};const fails=[];const CHK=(k,v)=>{out[k]=v;if(v!==true)fails.push(k+':'+JSON.stringify(v));};
const t0=Date.now();while(Date.now()-t0<4000&&(!T.$gameMap||!T.$gameMap.interpreter)){await new Promise(r=>setTimeout(r,50));}
/* buildTurnOrder 多动:构造 Scene_Battle 实例(method 通过原型,绕过构造) */
const proto=Object.getPrototypeOf(T.Scene_Battle.prototype||{});
const sc=Object.create(T.Scene_Battle.prototype);
if(!sc||!sc.buildTurnOrder){out.avail=false;CHK('hasBuildTurnOrder',out.avail===true);out.allOk=fails.length===0;out.fails=fails;return JSON.stringify(out);}
/* 假数据:成员 + 敌群 */
const mkActor=()=>{const o=Object.create(Game_Actor.prototype);o.isDead=()=>false;o.isActor=()=>true;o.specialFlag=()=>false;o.numActions=()=>1;o.actionPlusSet=()=>[];o.makeSpeed=()=>{o.turnAddSpeed=100;return 100;};return o;};
const mkEnemy=(id,tr)=>{const e=Object.create(Game_Enemy.prototype);e.enemyId=id;e.isDead=()=>false;e.specialFlag=()=>false;e.numActions=()=>1+(tr.times?1:0);e.actionPlusSet=()=>tr.plus?[1]:[];e.makeSpeed=()=>{e.turnAddSpeed=100;return 100;};return e;};
sc.partyMembers=[mkActor(),mkActor()];
sc.troop={aliveMembers:()=>[mkEnemy(25,{times:true}),mkEnemy(1,{times:false})]};sc.totalAssaultActive=false;
const order=sc.buildTurnOrder();
out.orderLen=order.length;out.enemyTimes=order.filter(x=>x.enemyId===25).length;
out.singleTimes=order.filter(x=>x.enemyId===1).length;
out.partyTimes=order.filter(x=>!x.enemyId).length;
CHK('doubleAttackEnemy',out.enemyTimes===2);
CHK('singleOnce',out.singleTimes===1);
CHK('partyOnce',out.partyTimes===2);
out.allOk=fails.length===0;out.fails=fails;
return JSON.stringify(out);})()
